import pickle
from fastapi import FastAPI, Request
from pydantic import BaseModel
import numpy as np

app = FastAPI()

# Load the best model at startup
with open('/app/models/best_model.pkl', 'rb') as f:
    best_model = pickle.load(f)

@app.get("/health")
def health_check():
    return {"status": "healthy", "model_loaded": True}

@app.get("/model-info")
def model_info():
    return {
        "model_name": "random_forest",
        "model_type": "RandomForestRegressor",
        "features_count": 8
    }

class PredictRequest(BaseModel):
    features: list[float]

class PredictBatchRequest(BaseModel):
    features_list: list[list[float]]

@app.post("/predict")
def predict(request: PredictRequest):
    features_array = np.array(request.features).reshape(1, -1)
    prediction = best_model.predict(features_array)[0]
    return {"prediction": prediction, "model_name": "random_forest"}

@app.post("/predict-batch")
def predict_batch(request: PredictBatchRequest):
    features_array = np.array(request.features_list)
    predictions = best_model.predict(features_array)
    return {
        "predictions": predictions.tolist(),
        "model_name": "random_forest",
        "count": len(predictions)
    }
